/* Shared/tested widget layout; browser copy is generated by scripts/sync-source-status.js. */
(function (root, factory) {
  if (typeof module === 'object' && module.exports) module.exports = factory();
  else root.WidgetLayout = factory();
})(typeof globalThis !== 'undefined' ? globalThis : this, function () {
  'use strict';
  function create(Homey, { document, view }) {
    const content = document.getElementById('widget-content');
    let ready = false,
      started = false,
      disposed = false,
      queued = false;
    let lastHeight, observer;
    const fit = (height) => {
      const heights = [view.innerHeight, view.visualViewport?.height].filter(
        (v) => Number.isFinite(v) && v > 0,
      );
      const fits = height !== null && heights.length > 0 && Math.min(...heights) >= height - 2;
      document.documentElement?.setAttribute('data-widget-fits', String(fits));
    };
    const measure = () => {
      const height = content?.getBoundingClientRect?.().height;
      return Number.isFinite(height) && height > 0 ? Math.ceil(height) + 2 : null;
    };
    const update = () => {
      if (disposed) return;
      const height = measure();
      fit(height);
      if (!ready) {
        ready = true;
        lastHeight = height;
        Homey.ready(height === null ? undefined : { height });
      } else if (height !== null && height !== lastHeight && Homey.setHeight) {
        lastHeight = height;
        // Keep normal overflow if the host rejects sizing. A later refresh can retry.
        try {
          Promise.resolve(Homey.setHeight(height)).catch(() => {
            if (lastHeight === height) lastHeight = undefined;
          });
        } catch {
          lastHeight = undefined;
        }
      }
    };
    const schedule = () => {
      if (disposed || queued) return;
      queued = true;
      const run = () => {
        queued = false;
        update();
      };
      if (view.requestAnimationFrame) view.requestAnimationFrame(run);
      else Promise.resolve().then(run);
    };
    function refresh() {
      update();
      if (started || disposed) return;
      started = true;
      if (content && view.ResizeObserver) {
        observer = new view.ResizeObserver(schedule);
        observer.observe(content);
      }
      view.addEventListener?.('resize', schedule, { passive: true });
      view.visualViewport?.addEventListener('resize', schedule, { passive: true });
      document.fonts?.ready.then(schedule);
    }
    function dispose() {
      disposed = true;
      observer?.disconnect();
      view.removeEventListener?.('resize', schedule);
      view.visualViewport?.removeEventListener('resize', schedule);
    }
    return { refresh, dispose };
  }
  return { create };
});
